     1→const express = require('express');
     2→const mongoose = require('mongoose');
     3→const cors = require('cors');
     4→const path = require('path');
     5→const http = require('http');
     6→const { WebSocketServer } = require('ws');
     7→const url = require('url');
     8→const jwt = require('jsonwebtoken');
     9→require('dotenv').config();
    10→
    11→const authRoutes = require('./routes/auth');
    12→const patientRoutes = require('./routes/patients');
    13→const appointmentRoutes = require('./routes/appointments');
    14→const paymentRoutes = require('./routes/payments');
    15→const dashboardRoutes = require('./routes/dashboard');
    16→const sessionRoutes = require('./routes/sessions');
    17→const uploadRoutes = require('./routes/uploads');
    18→const notificationRoutes = require('./routes/notifications');
    19→const walletRoutes = require('./routes/wallet');
    20→const siteRoutes = require('./routes/site');
    21→const pushRoutes = require('./routes/push');
    22→const webauthnRoutes = require('./routes/webauthn');
    23→const { registerWsClient, unregisterWsClient } = require('./utils/fireNotify');
    24→
    25→const app = express();
    26→const server = http.createServer(app);
    27→
    28→// ─── WebSocket Server ─────────────────────────────────────────────
    29→const wss = new WebSocketServer({ server, path: '/ws' });
    30→
    31→wss.on('connection', (ws, req) => {
    32→  const { query } = url.parse(req.url, true);
    33→  const token = query.token;
    34→  if (!token) { ws.close(); return; }
    35→  try {
    36→    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    37→    const userId = decoded.id;
    38→    registerWsClient(userId, ws);
    39→    ws.send(JSON.stringify({ type: 'connected', message: 'متصل بالإشعارات الفورية' }));
    40→    ws.on('close', () => unregisterWsClient(userId));
    41→    ws.on('error', () => unregisterWsClient(userId));
    42→  } catch {
    43→    ws.close();
    44→  }
    45→});
    46→
    47→// ─── Middleware ───────────────────────────────────────────────────
    48→app.use(cors({ origin: '*', credentials: true }));
    49→app.use(express.json({ limit: '50mb' }));
    50→app.use(express.urlencoded({ extended: true, limit: '50mb' }));
    51→app.use('/uploads', express.static(path.join(__dirname, 'uploads')));
    52→
    53→const MONGODB_URI = process.env.MONGODB_URI;
    54→const PORT = process.env.PORT || 3001;
    55→
    56→mongoose.connect(MONGODB_URI)
    57→  .then(() => console.log('✅ Connected to MongoDB'))
    58→  .catch(err => console.error('❌ MongoDB connection error:', err));
    59→
    60→// ─── Routes ───────────────────────────────────────────────────────
    61→app.use('/api/auth', authRoutes);
    62→app.use('/api/patients', patientRoutes);
    63→app.use('/api/appointments', appointmentRoutes);
    64→app.use('/api/payments', paymentRoutes);
    65→app.use('/api/dashboard', dashboardRoutes);
    66→app.use('/api/sessions', sessionRoutes);
    67→app.use('/api/uploads', uploadRoutes);
    68→app.use('/api/notifications', notificationRoutes);
    69→app.use('/api/wallet', walletRoutes);
    70→app.use('/api/site', siteRoutes);
    71→app.use('/api/push', pushRoutes);
    72→app.use('/api/webauthn', webauthnRoutes);
    73→
    74→app.get('/api/health', (req, res) => res.json({ status: 'ok', message: 'Dr. Wessam Clinic API v3' }));
    75→
    76→server.listen(PORT, () => {
    77→  console.log(`🚀 Server running on port ${PORT}`);
    78→});
    79→

