      </div>,
      { icon: '🔔', duration: 5000, style: { borderRadius: '12px', border: '1px solid #e2e8f0' } }
    );
    setUnreadCount(n => n + 1);
  }, []);

  const { connectWs, disconnectWs } = usePushNotifications({ onNotification: handleNotification });

