      phone: '01156798324',
      password: 'doctor123',
      role: 'doctor'
    });
    await doctor.save();
    res.json({ message: 'Doctor created', phone: '01156798324', password: 'doctor123' });
  } catch (err) {
    res.status(500).json({ message: err.message });
